#!/usr/bin/python3

import pyrob.core as rob
import random

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..2
_variant_order = list(range(3))
random.shuffle(_variant_order)

class Task:
    CHECKS = 1

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(8, 8)
            rob.set_parking_cell(7, 7)
            rob.goto(0, 0)
        elif idx == 1:
            rob.set_field_size(9, 9)
            rob.set_parking_cell(8, 8)
            rob.goto(0, 0)
        elif idx == 2:
            rob.set_field_size(10, 10)
            rob.set_parking_cell(9, 9)
            rob.goto(0, 0)

    def check_solution(self):
        return rob.is_parking_point()
